	DAGGER("Dagger"),
	FLAIL("Flail"),
	GUN("Gun"),
	MULTI_MELEE("Multi-Melee"),
	PARTISAN("Partisan"),
	PICKAXE("Pickaxe"),
	POLEARM("Polearm"),
	POLESTAFF("Polestaff"),
	POWERED_STAFF("Powered Staff"),
	POWERED_WAND("Powered Wand"),
	SALAMANDER("Salamander"),
	SCYTHE("Scythe"),
	SLASH_SWORD("Slash Sword"),
	SPEAR("Spear"),
	SPIKED("Spiked"),
	STAB_SWORD("Stab Sword"),
	STAFF("Staff"),
	THROWN("Thrown"),
	UNARMED("Unarmed"),
	WHIP("Whip"),

	/**
