import lombok.Builder;
import lombok.Value;

/**
 * A monster from the OSRS Wiki DPS calculator's monsters.json. The {@code id} is a real in-game NPC ID,
 * but it is not unique: a handful of monsters appear more than once, distinguished by {@code version}.
 *
 * @see <a href="https://github.com/weirdgloop/osrs-dps-calc/blob/main/cdn/json/monsters.json">monsters.json</a>
 */
@Value
@Builder(toBuilder = true)
public class Monster
{
	int id;
	String name;
	/**
	 * The monster's variant, e.g. "Dragon Slayer II". Empty string when the monster has no variants.
	 */
	String version;
	String image;
	int level;
	/**
	 * Attack speed in ticks.
	 */
	int speed;
	/**
	 * Free-text attack styles from the wiki, e.g. ["Slash", "Magic", "Ranged", "Dragonfire"]. Null in the
	 * JSON for a handful of monsters; {@link #getStyle()} normalises that to an empty list.
	 */
	List<String> style;
	int size;
	/**
	 * Display-only. Usually a plain number but sometimes annotated, e.g. "30 (Magic)". The calculator
	 * computes max hit itself and does not read this.
	 */
	@SerializedName("max_hit")
	String maxHit;
	Skills skills;
	Offensive offensive;
	Defensive defensive;
	List<MonsterAttribute> attributes;
	Immunities immunities;
	@SerializedName("is_slayer_monster")
	boolean slayerMonster;
	/**
	 * Null when the monster has no elemental weakness.
	 */
	Weakness weakness;
	/**
	 * Not present in monsters.json: these are the UI-controlled inputs (party size, invocation level,
	 * current hp, defence reductions, phase, ...) that the calculator scales the monster with. Null on a
	 * freshly deserialised monster; {@link #getInputs()} normalises that to the calculator's defaults.
	 */
	MonsterInputs inputs;

	public List<String> getStyle()
	{
		return style == null ? Collections.emptyList() : style;
	}

	public MonsterInputs getInputs()
	{
		return inputs == null ? MonsterInputs.defaults() : inputs;
	}

	public List<MonsterAttribute> getAttributes()
	{
		return attributes == null ? Collections.emptyList() : attributes;
	}

	@Value
	public static class Skills
	{
		int atk;
		int def;
		int hp;
		int magic;
		int ranged;
		int str;
	}

	@Value
	public static class Offensive
	{
		int atk;
		int magic;
		@SerializedName("magic_str")
		int magicStr;
		int ranged;
		@SerializedName("ranged_str")
		int rangedStr;
		int str;
	}

	@Value
	public static class Defensive
	{
		int stab;
		int slash;
		int crush;
		int magic;
		/**
		 * Ranged defence is split by ranged damage type.
		 */
		int heavy;
		int standard;
		int light;
		@SerializedName("flat_armour")
		int flatArmour;
	}

	@Value
	public static class Immunities
	{
		/**
		 * Null means the monster cannot be burnt at all.
		 */
		BurnImmunity burn;
	}

	@Value
	public static class Weakness
	{
		/**
		 * Spell element: "air", "water", "earth", "fire", or "none".
		 */
		String element;
		int severity;
	}
}

package com.github.diogogdias.bisfinder.calc.model;

import com.google.gson.TypeAdapter;
import com.google.gson.annotations.JsonAdapter;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.google.gson.stream.JsonWriter;
import java.io.IOException;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import lombok.Getter;

/**
 * The attributes a monster can have.
 *
 * @see <a href="https://oldschool.runescape.wiki/w/Monster_attribute">Monster attribute</a>
 */
@JsonAdapter(MonsterAttribute.Adapter.class)
public enum MonsterAttribute
{
	DEMON("demon"),
	DRAGON("dragon"),
	FIERY("fiery"),
	FLYING("flying"),
	GOLEM("golem"),
	KALPHITE("kalphite"),
	LEAFY("leafy"),
	PENANCE("penance"),
	RAT("rat"),
	SHADE("shade"),
	SPECTRAL("spectral"),
	UNDEAD("undead"),
	VAMPYRE_1("vampyre1"),
	VAMPYRE_2("vampyre2"),
	VAMPYRE_3("vampyre3"),
	XERICIAN("xerician"),

	/**
	 * Any attribute the wiki adds that this plugin does not know about yet. Never appears in the JSON.
	 */
	UNKNOWN("unknown");

	private static final List<MonsterAttribute> VAMPYRES = Arrays.asList(VAMPYRE_1, VAMPYRE_2, VAMPYRE_3);
	private static final Map<String, MonsterAttribute> BY_JSON_VALUE = new HashMap<>();

	static
	{
		for (MonsterAttribute attribute : values())
		{
			BY_JSON_VALUE.put(attribute.jsonValue.toLowerCase(Locale.ROOT), attribute);
		}
	}

	@Getter
	private final String jsonValue;

	MonsterAttribute(String jsonValue)
	{
		this.jsonValue = jsonValue;
	}

	/**
	 * Tolerant lookup: unknown attributes map to {@link #UNKNOWN} rather than throwing, so new wiki
	 * monsters do not break parsing.
	 */
	public static MonsterAttribute fromJson(String value)
	{
		if (value == null)
		{
			return UNKNOWN;
		}

		return BY_JSON_VALUE.getOrDefault(value.toLowerCase(Locale.ROOT), UNKNOWN);
	}

	public boolean isVampyre()
	{
		return VAMPYRES.contains(this);
	}

	static final class Adapter extends TypeAdapter<MonsterAttribute>
	{
		@Override
		public void write(JsonWriter out, MonsterAttribute value) throws IOException
		{
			out.value(value == null ? null : value.getJsonValue());
		}

		@Override
		public MonsterAttribute read(JsonReader in) throws IOException
		{
			if (in.peek() == JsonToken.NULL)
			{
				in.nextNull();
				return UNKNOWN;
			}

			// Qualified: an unqualified fromJson() would resolve to TypeAdapter.fromJson(String).
			return MonsterAttribute.fromJson(in.nextString());
		}
	}
}

