/**
 * Which targets tick the Wilderness box for themselves. The names are matched against the real monster list,
 * because a typo here would not fail loudly - it would just quietly never match.
 */
public class WildernessDefaultTest
{
	private static List<Monster> monsters;

	@BeforeClass
	public static void load()
	{
		monsters = read("/wiki/monsters.json", new TypeToken<List<Monster>>()
		{
		}.getType());
	}

	@Test
	public void wildernessBossesDefaultOn()
	{
		String[] wilderness = {
			"Callisto", "Artio", "Venenatis", "Spindel", "Vet'ion", "Calvar'ion",
			"Chaos Elemental", "Chaos Fanatic", "Crazy archaeologist",
			"Lava dragon", "Elder Chaos druid", "Mammoth",
			"Scorpia", "Scorpia's guardian", "Revenant dragon", "Revenant maledictus",
		};

		for (String name : wilderness)
		{
			assertTrue(name + " is in the Wilderness", BisFinderPanel.isWildernessOnly(named(name)));
		}
	}

	/**
	 * The King Black Dragon is the trap: it is billed as a Wilderness boss, but its lair is not in the
	 * Wilderness, so a revenant-ether weapon gets nothing there.
	 */
	@Test
	public void kingBlackDragonDefaultsOff()
	{
		assertFalse("the KBD lair is not in the Wilderness",
			BisFinderPanel.isWildernessOnly(named("King Black Dragon")));
	}

	/** A target found both in and out of the Wilderness is the player's call, not ours. */
	@Test
	public void everywhereElseDefaultsOff()
	{
		for (String name : new String[]{"Zulrah", "Vorkath", "Green dragon", "Chaos druid", "Tekton"})
		{
			assertFalse(name + " must not assume the Wilderness", BisFinderPanel.isWildernessOnly(named(name)));
		}
	}

	/** Every listed name must exist in the wiki data, or the default silently never fires. */
	private static Monster named(String name)
	{
		return monsters.stream().filter(m -> name.equals(m.getName())).findFirst()
			.orElseThrow(() -> new IllegalStateException("no monster named " + name));
	}

	private static <T> T read(String resource, java.lang.reflect.Type type)
	{
		try (InputStream in = WildernessDefaultTest.class.getResourceAsStream(resource))
		{
			return new Gson().fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), type);
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}
}

package com.github.diogogdias.bisfinder.calc;

import com.github.diogogdias.bisfinder.calc.model.EquipmentCategory;
import com.github.diogogdias.bisfinder.calc.model.EquipmentPiece;
import com.github.diogogdias.bisfinder.calc.model.Monster;
import com.github.diogogdias.bisfinder.calc.model.MonsterAttribute;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.Reader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.Objects;
import org.junit.Assume;
import org.junit.BeforeClass;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Parses the wiki calculator's equipment.json and monsters.json off disk (no network) through the Gson
 * models, to catch shape drift between the models and the real data.
 *
 * <p>Point {@code -Dbisfinder.wikiJsonDir=...} at a directory containing equipment.json and
 * monsters.json to use a different copy.
 */
public class WikiDataParsingTest
{
	private static final String DEFAULT_JSON_DIR =
		"C:\\Users\\User\\AppData\\Local\\Temp\\claude\\C--Users-User-runelite-plugins-bis-finder"
			+ "\\528c8f01-6022-495b-94a5-8035a2d3d2ab\\scratchpad\\osrs-dps-calc\\cdn\\json";

	private static final Type EQUIPMENT_TYPE = new TypeToken<List<EquipmentPiece>>()
	{
	}.getType();
	private static final Type MONSTERS_TYPE = new TypeToken<List<Monster>>()
	{
	}.getType();

	private static List<EquipmentPiece> equipment;
	private static List<Monster> monsters;

	@BeforeClass
	public static void parse() throws IOException
	{
		Path dir = Paths.get(System.getProperty("bisfinder.wikiJsonDir", DEFAULT_JSON_DIR));

		// This test validates the models against a full local weirdgloop dataset, which only exists when a dev
		// points -Dbisfinder.wikiJsonDir at a checkout. Skip (don't fail) when it is absent, so the suite is
		// green on CI and any other machine - the default path is one dev's now-deleted scratchpad clone.
		Assume.assumeTrue("wiki JSON dir not present: " + dir + " (set -Dbisfinder.wikiJsonDir to run)",
			Files.isReadable(dir.resolve("equipment.json")) && Files.isReadable(dir.resolve("monsters.json")));

		Gson gson = new Gson();

		try (Reader reader = Files.newBufferedReader(dir.resolve("equipment.json"), StandardCharsets.UTF_8))
		{
			equipment = gson.fromJson(reader, EQUIPMENT_TYPE);
		}

		try (Reader reader = Files.newBufferedReader(dir.resolve("monsters.json"), StandardCharsets.UTF_8))
		{
			monsters = gson.fromJson(reader, MONSTERS_TYPE);
		}
	}

	@Test
	public void testCounts()
	{
		assertEquals(5329, equipment.size());
		assertEquals(2852, monsters.size());
	}

	@Test
	public void testAbyssalWhip()
	{
		EquipmentPiece whip = equipment.stream()
			.filter(e -> e.getId() == 4151)
			.findFirst()
			.orElse(null);

		assertNotNull(whip);
		assertEquals("Abyssal whip", whip.getName());
		assertEquals("weapon", whip.getSlot());
		assertEquals(EquipmentCategory.WHIP, whip.getCategory());
		assertEquals(4, whip.getSpeed());
		assertEquals(82, whip.getOffensive().getSlash());
		assertEquals(82, whip.getBonuses().getStr());
		assertEquals(0, whip.getBonuses().getRangedStr());
		assertTrue(!whip.isTwoHanded());
	}

	@Test
	public void testVorkath()
	{
		Monster vorkath = monsters.stream()
			.filter(m -> m.getId() == 8058 && Objects.equals(m.getVersion(), "Dragon Slayer II"))
			.findFirst()
			.orElse(null);

		assertNotNull(vorkath);
		assertEquals("Vorkath", vorkath.getName());
		assertTrue(vorkath.getAttributes().contains(MonsterAttribute.DRAGON));
		assertTrue(vorkath.getAttributes().contains(MonsterAttribute.UNDEAD));
		assertEquals(204, vorkath.getDefensive().getMagic());
		assertEquals(460, vorkath.getSkills().getHp());
		assertTrue(vorkath.isSlayerMonster());
		assertEquals("fire", vorkath.getWeakness().getElement());
		assertEquals(40, vorkath.getWeakness().getSeverity());
	}

	@Test
	public void testNoUnknownEnumValues()
	{
		assertTrue(equipment.stream().noneMatch(e -> e.getCategory() == EquipmentCategory.UNKNOWN));
		assertTrue(monsters.stream()
			.flatMap(m -> m.getAttributes().stream())
			.noneMatch(a -> a == MonsterAttribute.UNKNOWN));
	}

	@Test
	public void testNullableFieldsAreTolerated()
	{
		// 1638 monsters have no weakness, 34 have no style, and burn immunity is null for most.
		assertTrue(monsters.stream().anyMatch(m -> m.getWeakness() == null));
		assertTrue(monsters.stream().allMatch(m -> m.getStyle() != null));
		assertTrue(monsters.stream().anyMatch(m -> m.getImmunities().getBurn() == null));
		// max_hit is a string in the JSON, but a bare number for some monsters.
		assertEquals("30 (Magic)", monsters.stream()
			.filter(m -> m.getId() == 8058 && Objects.equals(m.getVersion(), "Dragon Slayer II"))
			.findFirst()
			.orElseThrow(AssertionError::new)
			.getMaxHit());
	}
}

package com.github.diogogdias.bisfinder.calc;

import com.github.diogogdias.bisfinder.calc.model.EquipmentPiece;
import com.github.diogogdias.bisfinder.calc.model.Monster;
import com.github.diogogdias.bisfinder.calc.model.Spell;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.List;

/**
 * Loads the OSRS Wiki calculator's own data files from test resources, so the ported engine can be
 * checked against the numbers their test suite asserts.
 */
final class WikiTestData
{
	private static final Gson GSON = new Gson();

	private static List<EquipmentPiece> equipment;
	private static List<Monster> monsters;
	private static List<Spell> spells;

	private WikiTestData()
	{
	}

	static synchronized void load()
	{
		if (equipment != null)
		{
			return;
		}

		equipment = read("/wiki/equipment.json", new TypeToken<List<EquipmentPiece>>()
		{
		}.getType());
		monsters = read("/wiki/monsters.json", new TypeToken<List<Monster>>()
		{
		}.getType());
		spells = read("/wiki/spells.json", new TypeToken<List<Spell>>()
		{
		}.getType());

		CalcData.setAvailableEquipment(equipment);
		CalcData.setSpells(spells);
	}

	static EquipmentPiece equipmentById(int id)
	{
		load();
		return equipment.stream()
			.filter(e -> e.getId() == id)
			.findFirst()
			.orElseThrow(() -> new IllegalArgumentException("no equipment with id " + id));
	}

	/** The first equipment piece with this name; names are not unique across versions. */
	static EquipmentPiece equipmentByName(String name)
	{
		load();
		return equipment.stream()
			.filter(e -> name.equals(e.getName()))
			.findFirst()
			.orElseThrow(() -> new IllegalArgumentException("no equipment named " + name));
	}

	/** Their getTestMonsterById: the first monster with this id, as monster ids are not unique. */
	static Monster monsterById(int id)
	{
		load();
		return monsters.stream()
			.filter(m -> m.getId() == id)
			.findFirst()
			.orElseThrow(() -> new IllegalArgumentException("no monster with id " + id));
	}

	static Spell spellByName(String name)
	{
		load();
		return spells.stream()
			.filter(s -> s.getName().equals(name))
			.findFirst()
			.orElseThrow(() -> new IllegalArgumentException("no spell named " + name));
	}

	private static <T> T read(String resource, Type type)
	{
		try (InputStream in = WikiTestData.class.getResourceAsStream(resource))
		{
			if (in == null)
			{
				throw new IllegalStateException("missing test resource " + resource);
			}
			return GSON.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), type);
		}
		catch (IOException e)
		{
			throw new IllegalStateException("could not read " + resource, e);
		}
	}
}

package com.github.diogogdias.bisfinder.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.github.diogogdias.bisfinder.calc.CalcData;
import com.github.diogogdias.bisfinder.calc.model.Monster;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.List;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * Chambers of Xeric defence scaling, checked against the public wiki formula computed by hand (there is no
 * longer an oracle engine to diff against). Party member levels default to maxed, so party 1 with no
 * Challenge Mode leaves the base defence untouched, Challenge Mode adds a flat 50% (Tekton is the exception,
 * +20% below 4 players and +35% at 4+), and defence rises monotonically with party size.
 */
public class CoxScalingTest
{
	private static List<Monster> monsters;

	@BeforeClass
	public static void load()
	{
		monsters = read("/wiki/monsters.json", new TypeToken<List<Monster>>()
		{
		}.getType());
		CalcData.setAvailableEquipment(java.util.Collections.emptyList());
	}

	@Test
	public void tektonChallengeModeUsesItsOwnPercentages()
	{
		Monster tekton = named("Tekton");
		assertEquals("solo, no CM leaves base defence", 205, def(tekton, 1, false));
		assertEquals("Tekton CM below 4 players is +20%", 246, def(tekton, 1, true));
		assertEquals("Tekton CM at 4+ players is +35%", 287, def(tekton, 5, true));
	}

	@Test
	public void generalChallengeModeIsFlatFiftyPercent()
	{
		Monster muttadile = named("Muttadile");
		assertEquals(220, def(muttadile, 1, false));
		assertEquals("general CM is +50%", 330, def(muttadile, 1, true));
	}

	@Test
	public void defenceRisesWithPartySize()
	{
		Monster tekton = named("Tekton");
		int p1 = def(tekton, 1, false);
		int p5 = def(tekton, 5, false);
		int p15 = def(tekton, 15, false);
		assertTrue("more players raise defence", p5 > p1 && p15 > p5);
	}

	private static int def(Monster base, int party, boolean cm)
	{
		Monster withInputs = base.toBuilder()
			.inputs(base.getInputs().toBuilder().partySize(party).isFromCoxCm(cm).build())
			.build();
		return RaidScaling.scaleCox(withInputs).getSkills().getDef();
	}

	private static Monster named(String name)
	{
		return monsters.stream().filter(m -> name.equals(m.getName())).findFirst()
			.orElseThrow(() -> new IllegalStateException("no monster " + name));
	}

	private static <T> T read(String resource, Type type)
	{
		try (InputStream in = CoxScalingTest.class.getResourceAsStream(resource))
		{
			return new Gson().fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), type);
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}
}

package com.github.diogogdias.bisfinder.engine;

import static org.junit.Assert.assertEquals;

import com.github.diogogdias.bisfinder.calc.CalcData;
import com.github.diogogdias.bisfinder.calc.model.CombatStyleStance;
import com.github.diogogdias.bisfinder.calc.model.CombatStyleType;
import com.github.diogogdias.bisfinder.calc.model.EquipmentPiece;
import com.github.diogogdias.bisfinder.calc.model.Monster;
import com.github.diogogdias.bisfinder.calc.model.Player;
import com.github.diogogdias.bisfinder.calc.model.PlayerBuffs;
import com.github.diogogdias.bisfinder.calc.model.PlayerCombatStyle;
import com.github.diogogdias.bisfinder.calc.model.PlayerSkills;
import com.github.diogogdias.bisfinder.calc.model.Potion;
import com.github.diogogdias.bisfinder.calc.model.Prayer;
import com.github.diogogdias.bisfinder.calc.model.Spell;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.List;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * Golden-master DPS for the tricky weapons and monster mechanics, frozen from values that were verified exactly
 * against the weirdgloop-port oracle before that oracle was removed. Each maxed-stats, single-weapon setup
 * pins a specific behaviour (fang stab-only accuracy, scythe/two-hit splats, Colossal blade size scaling,
 * Dark bow two arrows, atlatl Strength scaling, Twisted bow scaling, Verzik's defence-level magic defence).
 * A change here means the engine's numbers moved - reconcile against dps.osrs.wiki before re-baselining.
 */
public class GoldenMasterTest
{
	private static final double EPS = 1e-4;
	private static final PlayerSkills MAX = new PlayerSkills(99, 99, 99, 99, 99, 99, 99, 99, 99);
	private static List<EquipmentPiece> equipment;
	private static List<Monster> monsters;

	@BeforeClass
	public static void load()
	{
		equipment = read("/wiki/equipment.json", new TypeToken<List<EquipmentPiece>>()
		{
		}.getType());
		monsters = read("/wiki/monsters.json", new TypeToken<List<Monster>>()
		{
		}.getType());
		CalcData.setAvailableEquipment(equipment);
		CalcData.setSpells(read("/wiki/spells.json", new TypeToken<List<Spell>>()
		{
		}.getType()));
	}

	@Test
	public void maidenMelee()
	{
		Monster maiden = monster("The Maiden of Sugadinti", "Normal");
		assertEquals(6.19050, melee("Osmumten's fang", CombatStyleType.STAB, maiden), EPS);
		assertEquals("fang accuracy is stab-only", 4.62649, melee("Osmumten's fang", CombatStyleType.SLASH, maiden), EPS);
		assertEquals(5.52610, melee("Blade of saeldor (c)", CombatStyleType.SLASH, maiden), EPS);
		assertEquals("scythe three splats", 7.54736, melee("Scythe of vitur", CombatStyleType.SLASH, maiden), EPS);
		assertEquals("two-hit weapon", 4.36045, melee("Sulphur blades", CombatStyleType.SLASH, maiden), EPS);
		assertEquals("colossal blade size scaling", 5.02405, melee("Colossal blade", CombatStyleType.SLASH, maiden), EPS);
	}

	@Test
	public void maidenRanged()
	{
		Monster maiden = monster("The Maiden of Sugadinti", "Normal");
		assertEquals("dark bow two arrows", 4.11533, ranged("Dark bow", "Dragon arrow", CombatStyleStance.RAPID, maiden), EPS);
		assertEquals("atlatl scales off strength", 4.03104, ranged("Eclipse atlatl", "Atlatl dart", CombatStyleStance.RAPID, maiden), EPS);
		assertEquals("twisted bow scaling", 8.76157, ranged("Twisted bow", "Dragon arrow", CombatStyleStance.RAPID, maiden), EPS);
	}

	@Test
	public void verzik()
	{
		Monster p2 = monster("Verzik Vitur", "Normal mode, Phase 2");
		Monster p3 = monster("Verzik Vitur", "Normal mode, Phase 3");
		assertEquals(3.34669, melee("Osmumten's fang", CombatStyleType.STAB, p2), EPS);
		assertEquals("fang slash uses normal accuracy", 2.73035, melee("Osmumten's fang", CombatStyleType.SLASH, p2), EPS);
		assertEquals(2.38569, ranged("Twisted bow", "Dragon arrow", CombatStyleStance.RAPID, p2), EPS);
		assertEquals("magic defends off defence level, not magic level", 2.96508, magic("Tumeken's shadow", p2), EPS);
		assertEquals(5.20251, melee("Osmumten's fang", CombatStyleType.STAB, p3), EPS);
		assertEquals(3.18453, magic("Tumeken's shadow", p3), EPS);
	}

	private double melee(String weapon, CombatStyleType type, Monster monster)
	{
		Player player = Player.builder().skills(MAX).boosts(Potion.SUPER_COMBAT.boost(MAX))
			.prayers(Collections.singletonList(Prayer.PIETY)).buffs(PlayerBuffs.builder().build())
			.style(new PlayerCombatStyle("s", type, CombatStyleStance.AGGRESSIVE))
			.equipment(Player.PlayerEquipment.builder().weapon(named(weapon)).build())
			.build().withGearBonuses(monster);
		return DpsEngine.meleeDps(player, monster);
	}

	private double ranged(String weapon, String ammo, CombatStyleStance stance, Monster monster)
	{
		Player player = Player.builder().skills(MAX).boosts(Potion.RANGING.boost(MAX))
			.prayers(Collections.singletonList(Prayer.RIGOUR)).buffs(PlayerBuffs.builder().build())
			.style(new PlayerCombatStyle("s", CombatStyleType.RANGED, stance))
			.equipment(Player.PlayerEquipment.builder().weapon(named(weapon)).ammo(named(ammo)).build())
			.build().withGearBonuses(monster);
		return DpsEngine.rangedDps(player, monster);
	}

	private double magic(String weapon, Monster monster)
	{
		Player player = Player.builder().skills(MAX).boosts(Potion.SATURATED_HEART.boost(MAX))
			.prayers(Collections.singletonList(Prayer.AUGURY)).buffs(PlayerBuffs.builder().build())
			.style(new PlayerCombatStyle("s", CombatStyleType.MAGIC, CombatStyleStance.ACCURATE))
			.equipment(Player.PlayerEquipment.builder().weapon(named(weapon)).build())
			.build().withGearBonuses(monster);
		return DpsEngine.magicDps(player, monster);
	}

	private static EquipmentPiece named(String name)
	{
		return equipment.stream().filter(p -> p.getName().equals(name)).findFirst()
			.orElseThrow(() -> new IllegalStateException("no item " + name));
	}

	private static Monster monster(String name, String versionContains)
	{
		return monsters.stream().filter(m -> name.equals(m.getName())
			&& m.getVersion() != null && m.getVersion().contains(versionContains)).findFirst()
			.orElseThrow(() -> new IllegalStateException("no monster " + name + " / " + versionContains));
	}

	private static <T> T read(String resource, Type type)
	{
		try (InputStream in = GoldenMasterTest.class.getResourceAsStream(resource))
		{
			return new Gson().fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), type);
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}
}

package com.github.diogogdias.bisfinder.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.github.diogogdias.bisfinder.calc.CalcData;
import com.github.diogogdias.bisfinder.calc.model.CombatStyleType;
import com.github.diogogdias.bisfinder.calc.model.EquipmentPiece;
import com.github.diogogdias.bisfinder.calc.model.Monster;
import com.github.diogogdias.bisfinder.calc.model.Player;
import com.github.diogogdias.bisfinder.calc.model.PlayerBuffs;
import com.github.diogogdias.bisfinder.calc.model.PlayerCombatStyle;
import com.github.diogogdias.bisfinder.calc.model.PlayerSkills;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.List;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * Powered staff base max hits, each pinned to the worked example printed on that staff's own wiki page.
 *
 * <p>The example is the point of these tests. The wiki writes these formulas as stacked fractions, which
 * flatten into ambiguous text when read as prose — the Warped sceptre's reads "⌊8(Magic Level)+9637⌋" — so
 * a formula is only trustworthy once it reproduces a level/max-hit pair the wiki states outright.
 */
public class PoweredStaffTest
{
	private static List<Monster> monsters;
	private static List<EquipmentPiece> equipment;

	@BeforeClass
	public static void load()
	{
		monsters = read("/wiki/monsters.json", new TypeToken<List<Monster>>()
		{
		}.getType());
		equipment = read("/wiki/equipment.json", new TypeToken<List<EquipmentPiece>>()
		{
		}.getType());
		CalcData.setAvailableEquipment(equipment);
	}

	/** Each pair is a level and the max hit the wiki states for it, with no magic-damage gear on. */
	@Test
	public void baseMaxHitsMatchTheWikisWorkedExamples()
	{
		assertBaseMax("Trident of the seas", 75, 20);
		assertBaseMax("Trident of the swamp", 78, 24);
		// Base max raised by 1 in the 2026 Summer Sweep-Up: floor(magic/3), was floor(magic/3) - 1.
		assertBaseMax("Sanguinesti staff", 82, 27);
		assertBaseMax("Sanguinesti staff", 123, 41);
		assertBaseMax("Accursed sceptre", 70, 17);
		assertBaseMax("Accursed sceptre", 123, 35);
		assertBaseMax("Warped sceptre", 62, 16);
		assertBaseMax("Warped sceptre", 99, 24);
		assertBaseMax("Eye of ayak", 99, 27);
		assertBaseMax("Tumeken's shadow", 60, 21);
	}

	/** The cosmetic and autocast variants share their base staff's formula. */
	@Test
	public void variantsMatchTheirBaseStaff()
	{
		assertEquals("the holy kit is cosmetic",
			baseMax("Sanguinesti staff", 99), baseMax("Holy sanguinesti staff", 99));
		assertEquals("(e) does not change the trident's max hit",
			baseMax("Trident of the seas", 99), baseMax("Trident of the seas (e)", 99));
		assertEquals("(a) does not change the sceptre's max hit",
			baseMax("Accursed sceptre", 99), baseMax("Accursed sceptre (a)", 99));
	}

	/** These were all scoring zero, so magic could never suggest them. */
	@Test
	public void theOnceUnscorablePoweredStaffsNowScore()
	{
		Monster target = named("Abyssal demon");
		for (String staff : new String[]{"Trident of the seas", "Trident of the swamp", "Sanguinesti staff",
			"Thammaron's sceptre", "Accursed sceptre", "Warped sceptre", "Eye of ayak"})
		{
			assertTrue(staff + " must score something", dps(staff, target, 99) > 0);
		}
	}

	/**
	 * The Bone staff is deliberately absent. The wiki's scraped formula ("⌊MagicLevel3⌋+5") contradicts the
	 * same page's own comparison against the trident, so it is left unmodelled rather than guessed at.
	 */
	@Test
	public void theBoneStaffIsStillUnmodelled()
	{
		assertEquals("an unverified staff must score nothing rather than a guess",
			0.0, dps("Bone staff", named("Abyssal demon"), 99), 0.0);
	}

	private static void assertBaseMax(String staff, int magic, int expected)
	{
		assertEquals(staff + " at " + magic + " magic", expected, baseMax(staff, magic));
	}

	/** The max hit with no magic-damage bonuses, which is the staff's raw formula. */
	private static int baseMax(String staff, int magic)
	{
		Monster target = named("Abyssal demon");
		return DpsEngine.estimate(player(staff, target, magic), target).getMaxHit();
	}

	private static double dps(String staff, Monster target, int magic)
	{
		return DpsEngine.dps(player(staff, target, magic), target);
	}

	private static Player player(String staffName, Monster target, int magic)
	{
		EquipmentPiece staff = weapon(staffName);
		PlayerCombatStyle style = PlayerCombatStyle.getCombatStylesForCategory(staff.getCategory()).stream()
			.filter(s -> s.getType() == CombatStyleType.MAGIC && s.getStance() != null)
			.findFirst()
			.orElseThrow(() -> new IllegalStateException("no magic style for " + staffName));

		return Player.builder()
			.skills(new PlayerSkills(99, 99, 99, magic, 99, 99, 99, 99, 99))
			.style(style)
			.equipment(Player.PlayerEquipment.builder().weapon(staff).build())
			.buffs(PlayerBuffs.builder().build())
			.build()
			.withGearBonuses(target);
	}

	private static EquipmentPiece weapon(String name)
	{
		return equipment.stream()
			.filter(p -> name.equals(p.getName()) && "weapon".equals(p.getSlot()))
			.filter(p -> !"Uncharged".equals(p.getVersion()))
			.findFirst()
			.orElseThrow(() -> new IllegalStateException("no weapon " + name));
	}

	private static Monster named(String name)
	{
		return monsters.stream().filter(m -> name.equals(m.getName())).findFirst()
			.orElseThrow(() -> new IllegalStateException("no monster " + name));
	}

	private static <T> T read(String resource, Type type)
	{
		try (InputStream in = PoweredStaffTest.class.getResourceAsStream(resource))
		{
			return new Gson().fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), type);
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}
}

package com.github.diogogdias.bisfinder.engine;

import org.junit.Assert;
import org.junit.Test;

/**
 * Hand-computed checks of the shared roll formulas. These pin the arithmetic transcription; game-level
 * correctness is covered later by parity tests against the reference outputs.
 */
public class RollMathTest
{
	private static final double EPS = 1e-9;

	@Test
	public void effectiveLevel()
	{
		// No prayer, no stance: 99 + 0 + 8.
		Assert.assertEquals(107, RollMath.effectiveLevel(99, 1.0, 0));
		// Piety strength (+23%), aggressive (+3): floor(99*1.23)=121, +3 +8.
		Assert.assertEquals(132, RollMath.effectiveLevel(99, 1.23, 3));
	}

	@Test
	public void maxHit()
	{
		// floor((132*64 + 320) / 640) = floor(8768/640) = 13.
		Assert.assertEquals(13, RollMath.maxHitFromEffective(132, 0));
		// floor((132*164 + 320) / 640) = floor(21968/640) = 34.
		Assert.assertEquals(34, RollMath.maxHitFromEffective(132, 100));
		Assert.assertEquals(0, RollMath.maxHitFromEffective(0, 0));
	}

	@Test
	public void rolls()
	{
		Assert.assertEquals(6848L, RollMath.attackRoll(107, 0));
		Assert.assertEquals(21648L, RollMath.attackRoll(132, 100));
		Assert.assertEquals(6848L, RollMath.defenceRoll(107, 0));
	}

	@Test
	public void accuracyWhenAttackExceedsDefence()
	{
		// atk > def: 1 - (def+2)/(2*(atk+1)).
		double expected = 1.0 - (1002.0) / (2.0 * 21649.0);
		Assert.assertEquals(expected, RollMath.normalAccuracy(21648, 1000), EPS);
	}

	@Test
	public void accuracyWhenDefenceExceedsAttack()
	{
		// atk <= def: atk/(2*(def+1)).
		double expected = 1000.0 / (2.0 * 21649.0);
		Assert.assertEquals(expected, RollMath.normalAccuracy(1000, 21648), EPS);
	}

	@Test
	public void accuracyIsBoundedAndMonotonic()
	{
		double low = RollMath.normalAccuracy(5000, 20000);
		double mid = RollMath.normalAccuracy(20000, 20000);
		double high = RollMath.normalAccuracy(40000, 20000);
		Assert.assertTrue(low >= 0.0 && high <= 1.0);
		Assert.assertTrue(low < mid && mid < high);
	}
}

package com.github.diogogdias.bisfinder.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.github.diogogdias.bisfinder.calc.CalcData;
import com.github.diogogdias.bisfinder.calc.model.CombatStyleType;
import com.github.diogogdias.bisfinder.calc.model.EquipmentPiece;
import com.github.diogogdias.bisfinder.calc.model.Monster;
import com.github.diogogdias.bisfinder.calc.model.Player;
import com.github.diogogdias.bisfinder.calc.model.PlayerBuffs;
import com.github.diogogdias.bisfinder.calc.model.PlayerCombatStyle;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.List;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * The target-specific rules that sit outside the damage maths: a style the target cannot be hurt by scores
 * nothing, and the revenant-ether weapons are powered up in the Wilderness.
 */
public class SpecialCasesTest
{
	private static List<Monster> monsters;
	private static List<EquipmentPiece> equipment;

	@BeforeClass
	public static void load()
	{
		monsters = read("/wiki/monsters.json", new TypeToken<List<Monster>>()
		{
		}.getType());
		equipment = read("/wiki/equipment.json", new TypeToken<List<EquipmentPiece>>()
		{
		}.getType());
		CalcData.setAvailableEquipment(equipment);
	}

	// --- style immunity -----------------------------------------------------------------------------

	/**
	 * Zulrah stopped being melee-immune on 7 May 2025 - it is now purely a matter of reach, and a halberd has
	 * it. A whip still cannot touch it, and a salamander's scorch is not long enough either.
	 */
	@Test
	public void onlyHalberdsReachZulrah()
	{
		for (Monster form : allNamed("Zulrah"))
		{
			String at = " at Zulrah (" + form.getVersion() + ")";
			assertEquals("a whip cannot reach" + at,
				0.0, dps(weapon("Abyssal whip"), CombatStyleType.SLASH, form, false), 0.0);
			assertEquals("a salamander cannot reach" + at,
				0.0, dps(weapon("Black salamander"), CombatStyleType.SLASH, form, false), 0.0);
			assertTrue("a noxious halberd reaches" + at,
				dps(weapon("Noxious halberd"), CombatStyleType.SLASH, form, false) > 0);
		}
	}

	@Test
	public void zulrahCanStillBeRanged()
	{
		Monster zulrah = named("Zulrah", "Serpentine");
		assertTrue("ranged still scores at Zulrah",
			dps(weapon("Twisted bow"), CombatStyleType.RANGED, zulrah, false) > 0);
	}

	/** Unlike Zulrah, the Kraken and the Leviathan have no halberd exception - melee cannot touch them at all. */
	@Test
	public void krakenAndLeviathanCannotBeMeleedEvenWithAHalberd()
	{
		Monster kraken = byId(494);
		assertEquals(0.0, dps(weapon("Abyssal whip"), CombatStyleType.SLASH, kraken, false), 0.0);
		assertEquals("a halberd is no help at the Kraken",
			0.0, dps(weapon("Noxious halberd"), CombatStyleType.SLASH, kraken, false), 0.0);
		assertTrue("ranged still scores at the Kraken",
			dps(weapon("Twisted bow"), CombatStyleType.RANGED, kraken, false) > 0);

		Monster leviathan = byId(12214);
		assertEquals("a halberd is no help at the Leviathan",
			0.0, dps(weapon("Noxious halberd"), CombatStyleType.SLASH, leviathan, false), 0.0);
	}

	@Test
	public void tektonCannotBeRanged()
	{
		Monster tekton = named("Tekton");
		assertEquals("Tekton shrugs off arrows",
			0.0, dps(weapon("Twisted bow"), CombatStyleType.RANGED, tekton, false), 0.0);
		assertTrue("melee still scores at Tekton",
			dps(weapon("Abyssal whip"), CombatStyleType.SLASH, tekton, false) > 0);
	}

	/**
	 * Halberds have hit every flying enemy since 25 June 2025, so the pre-change "salamanders only" rule must
	 * not be resurrected. A salamander's scorch reaches too; a whip still does not.
	 */
	@Test
	public void aviansiesAreMeleeableByReachAndSalamanderOnly()
	{
		Monster aviansie = byId(3169);
		assertEquals("a whip cannot reach a flying aviansie",
			0.0, dps(weapon("Abyssal whip"), CombatStyleType.SLASH, aviansie, false), 0.0);
		assertTrue("a halberd reaches a flying aviansie",
			dps(weapon("Crystal halberd"), CombatStyleType.SLASH, aviansie, false) > 0);
		assertTrue("a salamander's scorch reaches a flying aviansie",
			dps(weapon("Black salamander"), CombatStyleType.SLASH, aviansie, false) > 0);
	}

	// --- wilderness weapons -------------------------------------------------------------------------

	@Test
	public void chargedWildernessWeaponsGainFiftyPercentInTheWilderness()
	{
		assertScales("Craw's bow", CombatStyleType.RANGED);
		assertScales("Webweaver bow", CombatStyleType.RANGED);
		assertScales("Viggora's chainmace", CombatStyleType.CRUSH);
		assertScales("Ursine chainmace", CombatStyleType.CRUSH);
	}

	/** The max hit is +50%, and the extra accuracy makes the DPS gain strictly larger than that. */
	private void assertScales(String name, CombatStyleType type)
	{
		Monster target = named("Chaos Fanatic");
		EquipmentPiece charged = weapon(name, "Charged");

		int outside = maxHit(charged, type, target, false);
		int inside = maxHit(charged, type, target, true);
		assertEquals(name + " max hit is +50% in the Wilderness", outside + outside / 2, inside);

		assertTrue(name + " gains DPS in the Wilderness",
			dps(charged, type, target, true) > dps(charged, type, target, false));
	}

	@Test
	public void unchargedWildernessWeaponsGainNothing()
	{
		Monster target = named("Chaos Fanatic");
		EquipmentPiece uncharged = weapon("Craw's bow", "Uncharged");
		assertEquals("an uncharged Craw's bow is a plain bow",
			maxHit(uncharged, CombatStyleType.RANGED, target, false),
			maxHit(uncharged, CombatStyleType.RANGED, target, true));
	}

	@Test
	public void ordinaryWeaponsGainNothingInTheWilderness()
	{
		Monster target = named("Chaos Fanatic");
		EquipmentPiece whip = weapon("Abyssal whip");
		assertEquals("a whip is no better in the Wilderness",
			dps(whip, CombatStyleType.SLASH, target, false),
			dps(whip, CombatStyleType.SLASH, target, true), 1e-9);
	}

	// --- helpers ------------------------------------------------------------------------------------

	private static double dps(EquipmentPiece weapon, CombatStyleType type, Monster monster, boolean wildy)
	{
		return DpsEngine.dps(player(weapon, type, wildy, monster), monster);
	}

	private static int maxHit(EquipmentPiece weapon, CombatStyleType type, Monster monster, boolean wildy)
	{
		return DpsEngine.estimate(player(weapon, type, wildy, monster), monster).getMaxHit();
	}

	private static Player player(EquipmentPiece weapon, CombatStyleType type, boolean wildy, Monster monster)
	{
		return Player.builder()
			.style(styleFor(weapon, type))
			.equipment(Player.PlayerEquipment.builder().weapon(weapon).build())
			.buffs(PlayerBuffs.builder().inWilderness(wildy).build())
			.build()
			.withGearBonuses(monster);
	}

	private static PlayerCombatStyle styleFor(EquipmentPiece weapon, CombatStyleType type)
	{
		return PlayerCombatStyle.getCombatStylesForCategory(weapon.getCategory()).stream()
			.filter(s -> s.getType() == type && s.getStance() != null)
			.findFirst()
			.orElseThrow(() -> new IllegalStateException("no " + type + " style for " + weapon.getName()));
	}

	private static EquipmentPiece weapon(String name)
	{
		return equipment.stream()
			.filter(p -> name.equals(p.getName()) && "weapon".equals(p.getSlot()))
			.findFirst()
			.orElseThrow(() -> new IllegalStateException("no weapon " + name));
	}

	private static EquipmentPiece weapon(String name, String version)
	{
		return equipment.stream()
			.filter(p -> name.equals(p.getName()) && version.equals(p.getVersion()))
			.findFirst()
			.orElseThrow(() -> new IllegalStateException("no weapon " + name + " (" + version + ")"));
	}

	private static Monster named(String name)
	{
		return monsters.stream().filter(m -> name.equals(m.getName())).findFirst()
			.orElseThrow(() -> new IllegalStateException("no monster " + name));
	}

	private static Monster named(String name, String version)
	{
		return monsters.stream()
			.filter(m -> name.equals(m.getName()) && version.equals(m.getVersion()))
			.findFirst()
			.orElseThrow(() -> new IllegalStateException("no monster " + name + " (" + version + ")"));
	}

	private static List<Monster> allNamed(String name)
	{
		List<Monster> found = monsters.stream()
			.filter(m -> name.equals(m.getName()))
			.collect(java.util.stream.Collectors.toList());
		if (found.isEmpty())
		{
			throw new IllegalStateException("no monster " + name);
		}
		return found;
	}

	private static Monster byId(int id)
	{
		return monsters.stream().filter(m -> m.getId() == id).findFirst()
			.orElseThrow(() -> new IllegalStateException("no monster " + id));
	}

	private static <T> T read(String resource, Type type)
	{
		try (InputStream in = SpecialCasesTest.class.getResourceAsStream(resource))
		{
			return new Gson().fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), type);
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}
}

package com.github.diogogdias.bisfinder.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.github.diogogdias.bisfinder.calc.CalcData;
import com.github.diogogdias.bisfinder.calc.model.CombatStyleType;
import com.github.diogogdias.bisfinder.calc.model.EquipmentPiece;
import com.github.diogogdias.bisfinder.calc.model.Monster;
import com.github.diogogdias.bisfinder.calc.model.MonsterInputs;
import com.github.diogogdias.bisfinder.calc.model.Player;
import com.github.diogogdias.bisfinder.calc.model.PlayerBuffs;
import com.github.diogogdias.bisfinder.calc.model.PlayerCombatStyle;
import com.github.diogogdias.bisfinder.calc.model.PlayerSkills;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.List;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * The 2026 Summer Sweep-Up combat changes the engine models: the Tonalztics of ralos defence drain, the
 * Sanguinesti staff's higher base max and new damage proc, and the Inquisitor set's move to per-piece crush
 * bonuses with the mace no longer tripling it. Each value here was verified against the item's own wiki page.
 */
public class SummerSweepUpTest
{
	private static List<Monster> monsters;
	private static List<EquipmentPiece> equipment;

	@BeforeClass
	public static void load()
	{
		monsters = read("/wiki/monsters.json", new TypeToken<List<Monster>>()
		{
		}.getType());
		equipment = read("/wiki/equipment.json", new TypeToken<List<EquipmentPiece>>()
		{
		}.getType());
		CalcData.setAvailableEquipment(equipment);
	}

	// --- Tonalztics of ralos: defence drain (10% -> 12.5% of Magic level per hit) -------------------

	/**
	 * "Division ... reduces the target's Defence level by 12.5% of the target's Magic level upon a successful
	 * hit." General Graardor has Magic 80, so each hit drains floor(80 * 12.5%) = 10 Defence. Two hits must be
	 * identical to fighting a target whose Defence level is simply 20 lower - and this input did nothing at all
	 * before, so any effect at all is the fix.
	 */
	@Test
	public void tonalzticsDrainsDefenceByMagicLevel()
	{
		Monster graardor = named("General Graardor");
		assertEquals("Graardor's Magic level is the basis for the drain", 80, graardor.getSkills().getMagic());

		EquipmentPiece whip = weapon("Abyssal whip");
		double twoHits = dps(whip, CombatStyleType.SLASH, withTonalztic(graardor, 2));
		double manual20Lower = dps(whip, CombatStyleType.SLASH, withDefence(graardor, graardor.getSkills().getDef() - 20));

		assertEquals("two Tonalztics hits == 20 lower Defence", manual20Lower, twoHits, 1e-9);
		assertTrue("and it must actually raise DPS versus no drain",
			twoHits > dps(whip, CombatStyleType.SLASH, graardor));
	}

	// --- Sanguinesti staff: base max +1, and the new +8 damage proc --------------------------------

	/** New base max is floor(Magic/3): "27 at 82 Magic" and floor(99/3) = 33 (was 32). */
	@Test
	public void sanguinestiBaseMaxRaisedByOne()
	{
		assertEquals("floor(99/3) = 33", 33, bareMaxHit("Sanguinesti staff", 99));
		assertEquals("floor(82/3) = 27", 27, bareMaxHit("Sanguinesti staff", 82));
		assertEquals("the holy variant shares the formula", 33, bareMaxHit("Holy sanguinesti staff", 99));
	}

	/**
	 * The heal proc now deals 8 extra damage on 1 in 5 successful hits. Like the enchanted-bolt procs, it
	 * raises DPS but not the shown max hit. The DPS must equal the base expected hit plus accuracy * 0.2 * 8.
	 */
	@Test
	public void sanguinestiHealProcAddsDamage()
	{
		Player sang = bare("Sanguinesti staff", 99, named("Abyssal demon"));
		DpsEngine.Estimate e = DpsEngine.estimate(sang, named("Abyssal demon"));

		double withoutProc = RollMath.dps(RollMath.standardExpectedHit(e.getAccuracy(), e.getMaxHit()),
			sang.getAttackSpeed());
		double withProc = RollMath.dps(
			RollMath.standardExpectedHit(e.getAccuracy(), e.getMaxHit()) + e.getAccuracy() * 0.2 * 8.0,
			sang.getAttackSpeed());

		assertEquals("the proc is worth accuracy * 0.2 * 8 per attack", withProc, e.getDps(), 1e-9);
		assertTrue("which is strictly more than without it", e.getDps() > withoutProc);
		assertEquals("the shown max hit stays the base roll, not base + 8", 33, e.getMaxHit());
	}

	// --- Inquisitor: per-piece crush bonus, mace no longer triples ---------------------------------

	/**
	 * A spear's stab, slash and crush styles all use the Controlled stance, so its max hit differs between them
	 * only by the Inquisitor crush multiplier. The full set is +2.5% (0.5 + 1 + 1), spread across the pieces.
	 */
	@Test
	public void fullInquisitorIsTwoAndAHalfPercentOnCrush()
	{
		int stab = inquisitorMax(CombatStyleType.STAB, true, true, true);
		int crush = inquisitorMax(CombatStyleType.CRUSH, true, true, true);
		assertTrue("the modifier must actually change the floored max hit", crush > stab);
		assertEquals("full set is +2.5% on crush", stab * 1025 / 1000, crush);
	}

	/**
	 * The mace no longer triples the set bonus (that was removed for +7 strength / +7 crush on the mace
	 * itself). With the full armour it now gets the ordinary +2.5%, the same as any crush weapon - the spear
	 * proves the multiplier is 2.5%, so the mace on the same armour must land the same 2.5% on its own base.
	 */
	@Test
	public void theInquisitorMaceNoLongerTriplesTheBonus()
	{
		int maceFullArmour = inquisitorMaxWith("Inquisitor's mace", CombatStyleType.CRUSH, true, true, true);

		// The spear tests prove the multiplier is +2.5% (full) and +1% (one piece), weapon-independent - the
		// mace has no special branch any more, so it rides the same code. This is a golden pin at the same
		// gear: the old mace tripling (+7.5%) produced 49 here, so reverting the fix breaks this assertion.
		assertEquals("mace + full armour is +2.5%, not the old +7.5%", 47, maceFullArmour);
	}

	// --- helpers ------------------------------------------------------------------------------------

	private static Monster withTonalztic(Monster m, int hits)
	{
		return m.toBuilder()
			.inputs(m.getInputs().toBuilder()
				.defenceReductions(MonsterInputs.DefenceReductions.builder().tonalztic(hits).build())
				.build())
			.build();
	}

	private static Monster withDefence(Monster m, int def)
	{
		Monster.Skills s = m.getSkills();
		return m.toBuilder()
			.skills(new Monster.Skills(s.getAtk(), def, s.getHp(), s.getMagic(), s.getRanged(), s.getStr()))
			.build();
	}

	private static double dps(EquipmentPiece weapon, CombatStyleType type, Monster m)
	{
		return DpsEngine.dps(meleePlayer(weapon, type, m), m);
	}

	private static Player meleePlayer(EquipmentPiece weapon, CombatStyleType type, Monster m)
	{
		return Player.builder()
			.style(styleFor(weapon, type))
			.equipment(Player.PlayerEquipment.builder().weapon(weapon).build())
			.build()
			.withGearBonuses(m);
	}

	/** Max hit of a bare powered staff at the given Magic level, before any magic-damage gear. */
	private static int bareMaxHit(String staff, int magic)
	{
		Monster target = named("Abyssal demon");
		return DpsEngine.estimate(bare(staff, magic, target), target).getMaxHit();
	}

	private static Player bare(String staffName, int magic, Monster target)
	{
		EquipmentPiece staff = weapon(staffName);
		PlayerCombatStyle style = PlayerCombatStyle.getCombatStylesForCategory(staff.getCategory()).stream()
			.filter(s -> s.getType() == CombatStyleType.MAGIC && s.getStance() != null)
			.findFirst()
			.orElseThrow(() -> new IllegalStateException("no magic style for " + staffName));
		return Player.builder()
			.skills(new PlayerSkills(99, 99, 99, magic, 99, 99, 99, 99, 99))
			.style(style)
			.equipment(Player.PlayerEquipment.builder().weapon(staff).build())
			.buffs(PlayerBuffs.builder().build())
			.build()
			.withGearBonuses(target);
	}

	private static int inquisitorMax(CombatStyleType type, boolean helm, boolean body, boolean legs)
	{
		return inquisitorMaxWith("Zamorakian hasta", type, helm, body, legs);
	}

	private static int inquisitorMaxWith(String weaponName, CombatStyleType type, boolean helm, boolean body,
		boolean legs)
	{
		Monster target = named("Abyssal demon");
		EquipmentPiece weapon = weapon(weaponName);
		// Strength gear common to both styles, to lift the base max hit past ~40 where a 2.5% crush multiplier
		// crosses an integer boundary instead of flooring away. It is identical across stab and crush, so it
		// does not disturb the isolation of the Inquisitor modifier.
		Player.PlayerEquipment.PlayerEquipmentBuilder gear = Player.PlayerEquipment.builder().weapon(weapon)
			.neck(item("Amulet of torture"))
			.hands(item("Ferocious gloves"))
			.feet(item("Primordial boots"));
		if (helm)
		{
			gear.head(item("Inquisitor's great helm"));
		}
		if (body)
		{
			gear.body(item("Inquisitor's hauberk"));
		}
		if (legs)
		{
			gear.legs(item("Inquisitor's plateskirt"));
		}
		// Piety + super combat lift the base max hit high enough that a 2.5% multiplier changes the floored
		// number, so the modifier is actually visible rather than lost to rounding.
		PlayerSkills maxed = new PlayerSkills(99, 99, 99, 99, 99, 99, 99, 99, 99);
		Player p = Player.builder()
			.skills(maxed)
			.boosts(com.github.diogogdias.bisfinder.calc.model.Potion.SUPER_COMBAT.boost(maxed))
			.prayers(java.util.Collections.singletonList(
				com.github.diogogdias.bisfinder.calc.model.Prayer.PIETY))
			.style(styleFor(weapon, type))
			.equipment(gear.build())
			.build()
			.withGearBonuses(target);
		return DpsEngine.estimate(p, target).getMaxHit();
	}

	private static PlayerCombatStyle styleFor(EquipmentPiece weapon, CombatStyleType type)
	{
		return PlayerCombatStyle.getCombatStylesForCategory(weapon.getCategory()).stream()
			.filter(s -> s.getType() == type && s.getStance() != null)
			.findFirst()
			.orElseThrow(() -> new IllegalStateException("no " + type + " style for " + weapon.getName()));
	}

	private static EquipmentPiece item(String name)
	{
		return equipment.stream().filter(p -> name.equals(p.getName())).findFirst()
			.orElseThrow(() -> new IllegalStateException("no item " + name));
	}

	private static EquipmentPiece weapon(String name)
	{
		return equipment.stream()
			.filter(p -> name.equals(p.getName()) && "weapon".equals(p.getSlot()))
			.findFirst()
			.orElseThrow(() -> new IllegalStateException("no weapon " + name));
	}

	private static Monster named(String name)
	{
		return monsters.stream().filter(m -> name.equals(m.getName())).findFirst()
			.orElseThrow(() -> new IllegalStateException("no monster " + name));
	}

	private static <T> T read(String resource, Type type)
	{
		try (InputStream in = SummerSweepUpTest.class.getResourceAsStream(resource))
		{
			return new Gson().fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), type);
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}
}

package com.github.diogogdias.bisfinder.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.github.diogogdias.bisfinder.calc.CalcData;
import com.github.diogogdias.bisfinder.calc.model.CombatStyleType;
import com.github.diogogdias.bisfinder.calc.model.EquipmentPiece;
import com.github.diogogdias.bisfinder.calc.model.Monster;
import com.github.diogogdias.bisfinder.calc.model.Player;
import com.github.diogogdias.bisfinder.calc.model.PlayerBuffs;
import com.github.diogogdias.bisfinder.calc.model.PlayerCombatStyle;
import com.github.diogogdias.bisfinder.calc.model.Spell;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.List;
import org.junit.BeforeClass;
import org.junit.Test;

/**
 * The on-task black mask bonus and the demonbane weapons - two of the target-specific effects the clean-room
 * engine was scoring at flat base stats.
 */
public class TaskAndBaneTest
{
	private static List<Monster> monsters;
	private static List<EquipmentPiece> equipment;
	private static List<Spell> spells;

	@BeforeClass
	public static void load()
	{
		monsters = read("/wiki/monsters.json", new TypeToken<List<Monster>>()
		{
		}.getType());
		equipment = read("/wiki/equipment.json", new TypeToken<List<EquipmentPiece>>()
		{
		}.getType());
		spells = read("/wiki/spells.json", new TypeToken<List<Spell>>()
		{
		}.getType());
		CalcData.setAvailableEquipment(equipment);
		CalcData.setSpells(spells);
	}

	// --- on task ------------------------------------------------------------------------------------

	/** The reported bug: only the melee tab moved when "On task" was ticked. */
	@Test
	public void anImbuedMaskLiftsEveryStyleOnTask()
	{
		Monster target = named("Abyssal demon");

		assertTrue("melee gains from an imbued mask on task",
			onTask(item("Slayer helmet (i)"), weapon("Abyssal whip"), CombatStyleType.SLASH, target)
				> offTask(item("Slayer helmet (i)"), weapon("Abyssal whip"), CombatStyleType.SLASH, target));
		assertTrue("ranged gains from an imbued mask on task",
			onTask(item("Slayer helmet (i)"), weapon("Twisted bow"), CombatStyleType.RANGED, target)
				> offTask(item("Slayer helmet (i)"), weapon("Twisted bow"), CombatStyleType.RANGED, target));
		assertTrue("magic gains from an imbued mask on task",
			castOnTask(item("Slayer helmet (i)"), weapon("Kodai wand"), target, true)
				> castOnTask(item("Slayer helmet (i)"), weapon("Kodai wand"), target, false));
	}

	/** A staff scores nothing without a spell, so the magic side has to actually be casting one. */
	private static double castOnTask(EquipmentPiece head, EquipmentPiece weapon, Monster m, boolean onTask)
	{
		Player p = player(head, weapon, CombatStyleType.MAGIC, m, onTask, null).toBuilder()
			.spell(Spell.byName("Fire Surge", spells))
			.build()
			.withGearBonuses(m);
		return DpsEngine.dps(p, m);
	}

	/** Only the imbued variants carry the Ranged and Magic bonus; the plain helm is melee-only. */
	@Test
	public void anUnimbuedMaskIsMeleeOnly()
	{
		Monster target = named("Abyssal demon");

		assertTrue("melee still gains from a plain helm",
			onTask(item("Slayer helmet"), weapon("Abyssal whip"), CombatStyleType.SLASH, target)
				> offTask(item("Slayer helmet"), weapon("Abyssal whip"), CombatStyleType.SLASH, target));
		assertEquals("ranged gains nothing from a plain helm",
			offTask(item("Slayer helmet"), weapon("Twisted bow"), CombatStyleType.RANGED, target),
			onTask(item("Slayer helmet"), weapon("Twisted bow"), CombatStyleType.RANGED, target), 1e-9);
	}

	/**
	 * The helm the game actually hands out is a coloured one, and "Slayer helmet" is only the prefix of the
	 * plain variant - so a prefix match left most players with no on-task bonus at all.
	 */
	@Test
	public void themedSlayerHelmetsCountAsABlackMask()
	{
		Monster target = named("Abyssal demon");

		for (String helm : new String[]{"Purple slayer helmet (i)", "Hydra slayer helmet (i)",
			"Araxyte slayer helmet (i)", "Tzkal slayer helmet (i)", "Oathplate slayer helmet (i)",
			"Black mask (i)"})
		{
			assertEquals(helm + " must match the plain helm's on-task bonus",
				onTask(item("Slayer helmet (i)"), weapon("Abyssal whip"), CombatStyleType.SLASH, target),
				onTask(item(helm), weapon("Abyssal whip"), CombatStyleType.SLASH, target), 1e-9);
		}
	}

	/**
	 * "This stacks multiplicatively with both Void Knight equipment and the Slayer helm (i)" - the lance must
	 * not swallow the mask's bonus, which is what folding both into one either/or chain did.
	 */
	@Test
	public void theDragonHunterLanceStacksWithTheMask()
	{
		Monster dragon = named("Vorkath", "Post-quest");

		double lanceOnly = offTask(null, weapon("Dragon hunter lance"), CombatStyleType.STAB, dragon);
		double lanceAndMask = onTask(item("Slayer helmet (i)"), weapon("Dragon hunter lance"),
			CombatStyleType.STAB, dragon);

		assertTrue("the lance and the mask must stack", lanceAndMask > lanceOnly);
	}

	/** Mod Ash: "Salve effects override the Slayer helm / black mask effects." */
	@Test
	public void theSalveOverridesTheMaskRatherThanStacking()
	{
		Monster undead = named("Vorkath", "Post-quest");

		double salveOnly = onTask(null, weapon("Abyssal whip"), CombatStyleType.SLASH, undead, "Salve amulet(ei)");
		double salveAndMask = onTask(item("Slayer helmet (i)"), weapon("Abyssal whip"), CombatStyleType.SLASH,
			undead, "Salve amulet(ei)");

		assertEquals("the mask must add nothing on top of a salve", salveOnly, salveAndMask, 1e-9);
	}

	/** The wand is a staff, so its bonus used to fire only when bashing a dragon rather than casting at one. */
	@Test
	public void theDragonHunterWandBoostsItsSpells()
	{
		Monster dragon = named("Vorkath", "Post-quest");
		Monster notADragon = named("Abyssal demon");

		// The wand's own stats are weaker than a Kodai's, so against a dragon it can only come out ahead if
		// its dragonbane bonus is actually reaching the spell.
		assertTrue("the wand's spell must beat a Kodai's against a dragon",
			cast(weapon("Dragon hunter wand"), dragon) > cast(weapon("Kodai wand"), dragon));
		assertTrue("and must lose to a Kodai against something that is not a dragon",
			cast(weapon("Dragon hunter wand"), notADragon) < cast(weapon("Kodai wand"), notADragon));
	}

	// --- demonbane ----------------------------------------------------------------------------------

	/**
	 * The same target with and without the demon attribute, so nothing but demonbane can move the number.
	 * Comparing two real monsters would confound it with their different defences, and the smallest bonus
	 * (Burning claws, +5%) is invisible in the max hit alone - 5% of a bare weapon's 16 floors straight back
	 * to 16 - so this scores DPS, which carries the accuracy half too.
	 */
	@Test
	public void demonbaneWeaponsHitDemonsHarder()
	{
		Monster plain = named("Aberrant spectre");
		Monster demon = asDemon(plain);

		for (String name : new String[]{"Arclight", "Emberlight", "Darklight", "Silverlight", "Burning claws"})
		{
			assertTrue(name + " must gain against a demon",
				offTask(null, weapon(name), CombatStyleType.SLASH, demon)
					> offTask(null, weapon(name), CombatStyleType.SLASH, plain));
		}

		assertTrue("the Scorching bow must gain against a demon",
			offTask(null, weapon("Scorching bow"), CombatStyleType.RANGED, demon)
				> offTask(null, weapon("Scorching bow"), CombatStyleType.RANGED, plain));
	}

	private static Monster asDemon(Monster monster)
	{
		return monster.toBuilder()
			.attributes(java.util.Collections.singletonList(
				com.github.diogogdias.bisfinder.calc.model.MonsterAttribute.DEMON))
			.build();
	}

	/** Arclight is +70% damage, so a demon takes 170/100 of what a non-demon does off the same setup. */
	@Test
	public void arclightIsSeventyPercent()
	{
		int off = maxHit(weapon("Arclight"), CombatStyleType.SLASH, named("Aberrant spectre"));
		int on = maxHit(weapon("Arclight"), CombatStyleType.SLASH, named("Abyssal demon"));
		assertEquals("Arclight's demon max hit is +70%", off * 170 / 100, on);
	}

	/** Duke Sucellus resists 30% of demonbane, turning Arclight's 70% into 49%. */
	@Test
	public void dukeSucellusResistsDemonbane()
	{
		int base = maxHit(weapon("Arclight"), CombatStyleType.SLASH, named("Aberrant spectre"));
		int duke = maxHit(weapon("Arclight"), CombatStyleType.SLASH, named("Duke Sucellus", "Post-quest, Awake"));
		assertEquals("Duke takes Arclight at 49%, not 70%", base * 149 / 100, duke);
	}

	/**
	 * Leafy creatures matter far more as an immunity than as a bonus: "they can only be damaged with
	 * leaf-bladed weapons, broad ammunition, or the Magic Dart spell; they are immune to any other types of
	 * attacks." A scythe at a Kurask scored full damage before this.
	 */
	@Test
	public void onlyLeafBladedBroadAndMagicDartHurtALeafyCreature()
	{
		Monster kurask = named("Kurask");

		assertEquals("a scythe cannot hurt a Kurask", 0.0,
			offTask(null, weapon("Scythe of vitur"), CombatStyleType.SLASH, kurask), 0.0);
		assertTrue("a leaf-bladed battleaxe can",
			offTask(null, weapon("Leaf-bladed battleaxe"), CombatStyleType.CRUSH, kurask) > 0);
		assertEquals("a twisted bow with ordinary arrows cannot", 0.0,
			ranged(weapon("Twisted bow"), item("Dragon arrow"), kurask), 0.0);
		assertTrue("a bow with broad arrows can",
			ranged(weapon("Twisted bow"), item("Broad arrows"), kurask) > 0);
		assertEquals("a Kodai casting Fire Surge cannot", 0.0, spellAt("Fire Surge", kurask), 0.0);
		assertTrue("Magic Dart can", spellAt("Magic Dart", kurask) > 0);
	}

	/** Only the battleaxe carries the 17.5%; the sword and spear are merely allowed to hit. */
	@Test
	public void onlyTheLeafBladedBattleaxeGetsTheDamageBonus()
	{
		Monster kurask = named("Kurask");
		Monster plain = kurask.toBuilder().attributes(java.util.Collections.emptyList()).build();

		assertEquals("the battleaxe is +17.5% against a leafy creature",
			maxHit(weapon("Leaf-bladed battleaxe"), CombatStyleType.CRUSH, plain) * 47 / 40,
			maxHit(weapon("Leaf-bladed battleaxe"), CombatStyleType.CRUSH, kurask));
		assertEquals("the sword gets nothing",
			maxHit(weapon("Leaf-bladed sword"), CombatStyleType.SLASH, plain),
			maxHit(weapon("Leaf-bladed sword"), CombatStyleType.SLASH, kurask));
	}

	/** Every keris keeps the original's 33% against kalphites. */
	@Test
	public void aKerisIsThirtyThreePercentAgainstKalphites()
	{
		Monster kalphite = named("Kalphite Worker");
		Monster plain = kalphite.toBuilder().attributes(java.util.Collections.emptyList()).build();

		for (String name : new String[]{"Keris", "Keris partisan", "Keris partisan of breaching",
			"Keris partisan of the sun", "Keris partisan of corruption"})
		{
			assertEquals(name + " is +33% against a kalphite",
				maxHit(weapon(name), CombatStyleType.STAB, plain) * 133 / 100,
				maxHit(weapon(name), CombatStyleType.STAB, kalphite));
		}
	}

	/** "this variant has a damage bonus of 15%, down from the base weapon's 33%" - it trades it for ToA stats. */
	@Test
	public void theKerisPartisanOfAmascutIsOnlyFifteenPercent()
	{
		Monster kalphite = named("Kalphite Worker");
		Monster plain = kalphite.toBuilder().attributes(java.util.Collections.emptyList()).build();

		assertEquals("the amascut variant is +15%, not +33%",
			maxHit(weapon("Keris partisan of amascut"), CombatStyleType.STAB, plain) * 115 / 100,
			maxHit(weapon("Keris partisan of amascut"), CombatStyleType.STAB, kalphite));
	}

	@Test
	public void theBarroniteMaceIsFifteenPercentAgainstGolems()
	{
		Monster golem = named("Black golem");
		Monster plain = golem.toBuilder().attributes(java.util.Collections.emptyList()).build();

		assertEquals("the Barronite mace is +15% against a golem",
			maxHit(weapon("Barronite mace"), CombatStyleType.CRUSH, plain) * 23 / 20,
			maxHit(weapon("Barronite mace"), CombatStyleType.CRUSH, golem));
	}

	/** The rat bone weapons add a flat 10, not a percentage - and the Bone dagger is not one of them. */
	@Test
	public void ratbaneWeaponsAddAFlatTenAgainstRats()
	{
		Monster scurrius = named("Scurrius");
		Monster plain = scurrius.toBuilder().attributes(java.util.Collections.emptyList()).build();

		assertEquals("the Bone mace adds a flat 10 against a rat",
			maxHit(weapon("Bone mace"), CombatStyleType.CRUSH, plain) + 10,
			maxHit(weapon("Bone mace"), CombatStyleType.CRUSH, scurrius));
		assertEquals("the Bone dagger is not a ratbane weapon",
			maxHit(weapon("Bone dagger"), CombatStyleType.STAB, plain),
			maxHit(weapon("Bone dagger"), CombatStyleType.STAB, scurrius));
	}

	@Test
	public void anOrdinarySwordGainsNothingAgainstADemon()
	{
		assertEquals("a whip is no better against a demon",
			maxHit(weapon("Abyssal whip"), CombatStyleType.SLASH, named("Aberrant spectre")),
			maxHit(weapon("Abyssal whip"), CombatStyleType.SLASH, named("Abyssal demon")));
	}

	// --- helpers ------------------------------------------------------------------------------------


	private static double onTask(EquipmentPiece head, EquipmentPiece weapon, CombatStyleType type, Monster m)
	{
		return onTask(head, weapon, type, m, null);
	}

	private static double onTask(EquipmentPiece head, EquipmentPiece weapon, CombatStyleType type, Monster m,
		String neck)
	{
		return DpsEngine.dps(player(head, weapon, type, m, true, neck), m);
	}

	private static double offTask(EquipmentPiece head, EquipmentPiece weapon, CombatStyleType type, Monster m)
	{
		return DpsEngine.dps(player(head, weapon, type, m, false, null), m);
	}

	private static double cast(EquipmentPiece weapon, Monster m)
	{
		Player p = player(null, weapon, CombatStyleType.MAGIC, m, false, null).toBuilder()
			.spell(Spell.byName("Fire Surge", spells))
			.build()
			.withGearBonuses(m);
		return DpsEngine.dps(p, m);
	}

	private static int maxHit(EquipmentPiece weapon, CombatStyleType type, Monster m)
	{
		return DpsEngine.estimate(player(null, weapon, type, m, false, null), m).getMaxHit();
	}

	/** Ranged with a particular ammunition loaded, which is what decides a leafy creature's immunity. */
	private static double ranged(EquipmentPiece weapon, EquipmentPiece ammo, Monster m)
	{
		Player p = player(null, weapon, CombatStyleType.RANGED, m, false, null).toBuilder()
			.equipment(Player.PlayerEquipment.builder().weapon(weapon).ammo(ammo).build())
			.build()
			.withGearBonuses(m);
		return DpsEngine.dps(p, m);
	}

	private static double spellAt(String spellName, Monster m)
	{
		EquipmentPiece staff = weapon("Kodai wand");
		Player p = player(null, staff, CombatStyleType.MAGIC, m, false, null).toBuilder()
			.spell(Spell.byName(spellName, spells))
			.build()
			.withGearBonuses(m);
		return DpsEngine.dps(p, m);
	}

	private static Player player(EquipmentPiece head, EquipmentPiece weapon, CombatStyleType type, Monster m,
		boolean onTask, String neck)
	{
		Player.PlayerEquipment gear = Player.PlayerEquipment.builder().weapon(weapon).head(head).build();
		if (neck != null)
		{
			gear = gear.withSlot("neck", item(neck));
		}
		return Player.builder()
			.style(styleFor(weapon, type))
			.equipment(gear)
			.buffs(PlayerBuffs.builder().onSlayerTask(onTask).build())
			.build()
			.withGearBonuses(m);
	}

	private static PlayerCombatStyle styleFor(EquipmentPiece weapon, CombatStyleType type)
	{
		return PlayerCombatStyle.getCombatStylesForCategory(weapon.getCategory()).stream()
			.filter(s -> s.getType() == type && s.getStance() != null)
			.findFirst()
			.orElseThrow(() -> new IllegalStateException("no " + type + " style for " + weapon.getName()));
	}

	private static EquipmentPiece item(String name)
	{
		return equipment.stream().filter(p -> name.equals(p.getName())).findFirst()
			.orElseThrow(() -> new IllegalStateException("no item " + name));
	}

	private static EquipmentPiece weapon(String name)
	{
		return equipment.stream()
			.filter(p -> name.equals(p.getName()) && "weapon".equals(p.getSlot()))
			.filter(p -> p.getVersion() == null || !"Uncharged".equals(p.getVersion()))
			.findFirst()
			.orElseThrow(() -> new IllegalStateException("no weapon " + name));
	}

	private static Monster named(String name)
	{
		return monsters.stream().filter(m -> name.equals(m.getName())).findFirst()
			.orElseThrow(() -> new IllegalStateException("no monster " + name));
	}

	private static Monster named(String name, String version)
	{
		return monsters.stream()
			.filter(m -> name.equals(m.getName()) && version.equals(m.getVersion()))
			.findFirst()
			.orElseThrow(() -> new IllegalStateException("no monster " + name + " (" + version + ")"));
	}

	private static <T> T read(String resource, Type type)
	{
		try (InputStream in = TaskAndBaneTest.class.getResourceAsStream(resource))
		{
			return new Gson().fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), type);
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}
}
